import{_ as s,o as a,c as o,ag as i}from"./chunks/framework.BwSLX4ak.js";const h=JSON.parse('{"title":"QQMusic","description":"","frontmatter":{},"headers":[],"relativePath":"en/allmusic/qqmusic.md","filePath":"en/allmusic/qqmusic.md"}'),t={name:"en/allmusic/qqmusic.md"};function c(l,e,n,d,r,u){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="qqmusic" tabindex="-1">QQMusic <a class="header-anchor" href="#qqmusic" aria-label="Permalink to &quot;QQMusic&quot;">​</a></h1><p>AllMusic_QQMusic uses the API ID <code>qqmusic</code>. It supports keyword search, song information, album covers, timed lyrics, and available playback URLs returned by QQ Music. It can also extract identifiers from supported song and playlist links.</p><h2 id="search-and-default-source" tabindex="-1">Search and default source <a class="header-anchor" href="#search-and-default-source" aria-label="Permalink to &quot;Search and default source&quot;">​</a></h2><p>After following the <a href="./#installation">installation steps</a>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/music search qqmusic 稻香</span></span></code></pre></div><p>If AllMusic&#39;s <code>defaultApi</code> is <code>qqmusic</code>, omit the API ID:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/music search 稻香</span></span></code></pre></div><p>Songs usually use QQ Music&#39;s <code>songmid</code>; playlists use numeric IDs. The implementation extracts identifiers from <code>songmid</code>, <code>disstid</code> / <code>dissid</code> parameters and supported song, songdetail, playlist, and taoge paths. A browser share-page URL is not necessarily an audio URL; let the source resolve it.</p><h2 id="cookies-and-playback" tabindex="-1">Cookies and playback <a class="header-anchor" href="#cookies-and-playback" aria-label="Permalink to &quot;Cookies and playback&quot;">​</a></h2><p>QQMusic reads the cookie list already loaded by AllMusic from its own <code>cookie.json</code>. QQMusic&#39;s <code>reload(File)</code> has no separate configuration-file logic, so there is no need for a <code>qqmusic.yml</code>.</p><p>If a logged-in session is needed, save your QQ Music account&#39;s data using AllMusic&#39;s cookie format, then reload through the procedure supported by your AllMusic version or restart. Without cookies, public search results and some song URLs may still work. Playability depends on the platform&#39;s response and account permissions. The extension does not provide playback links that the platform has not authorized and returned normally.</p><p>Do not put real cookies in documentation examples or public repositories. <code>QQSong.debug</code> defaults to <code>false</code>.</p><h2 id="build-from-source" tabindex="-1">Build from source <a class="header-anchor" href="#build-from-source" aria-label="Permalink to &quot;Build from source&quot;">​</a></h2><p>Put the core JAR matching your AllMusic version in the project&#39;s <code>libs/</code>, then run:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gradlew.bat build</span></span></code></pre></div><p>On Linux/macOS, use <code>./gradlew build</code>. Output is in <code>build/libs/</code>; <code>build.gradle</code> determines the version. Do not copy a fixed filename from an old README. The dependency is <code>compileOnly</code>; AllMusic supplies the core and shared libraries at runtime.</p><p><a href="https://github.com/hutuyee/AllMusic_QQMusic" target="_blank" rel="noreferrer">QQMusic source</a> · <a href="./troubleshooting.html">Troubleshooting</a></p>',17)])])}const m=s(t,[["render",c]]);export{h as __pageData,m as default};
